namespace EanEtikety {
public class ArtShape:IDisposable {public GraphicsPath Path;public Color Fill=Color.Black;public Bitmap Bitmap;public RectangleF ImageBounds;public RectangleF? CanvasClip;public ArtShape Copy(){return new ArtShape{Path=(GraphicsPath)Path.Clone(),Fill=Fill,Bitmap=Bitmap==null?null:(Bitmap)Bitmap.Clone(),ImageBounds=ImageBounds,CanvasClip=CanvasClip,Clip=Clip,Rotation=Rotation,Pivot=Pivot,Bars=Bars,Element=Element};}public RectangleF Clip;public double Rotation;public PointF Pivot;public bool Bars;public int Element=-1;public void Dispose(){Path.Dispose();if(Bitmap!=null)Bitmap.Dispose();}}
public class VectorScene:IDisposable {
 public double Width,Height;public List<ArtShape> Shapes=new List<ArtShape>();
 public void Draw(Graphics g,RectangleF destination,bool monochrome){var saved=g.Save();g.SetClip(destination,CombineMode.Intersect);g.TranslateTransform(destination.X,destination.Y);g.ScaleTransform(destination.Width/(float)Width,destination.Height/(float)Height);foreach(var item in Shapes){WorkContext.Check();var clip=g.Save();if(item.CanvasClip.HasValue)g.SetClip(item.CanvasClip.Value,CombineMode.Intersect);using(var transform=ElementTransform.Matrix(item.Rotation,item.Pivot))g.MultiplyTransform(transform);g.SetClip(item.Clip,CombineMode.Intersect);g.SmoothingMode=monochrome||(item.Bars&&Math.Abs(item.Rotation%90)<.00001)?SmoothingMode.None:SmoothingMode.AntiAlias;g.PixelOffsetMode=PixelOffsetMode.Default;if(item.Bitmap!=null){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(item.Bitmap,item.ImageBounds);}else using(var brush=new SolidBrush(item.Fill))g.FillPath(brush,item.Path);g.Restore(clip);}g.Restore(saved);}
 public void TranslateElement(int index,float dx,float dy){using(var matrix=new Matrix()){matrix.Translate(dx,dy);foreach(var shape in Shapes)if(shape.Element==index){shape.Path.Transform(matrix);var image=shape.ImageBounds;image.Offset(dx,dy);shape.ImageBounds=image;shape.Pivot=new PointF(shape.Pivot.X+dx,shape.Pivot.Y+dy);{var clip=shape.Clip;clip.Offset(dx,dy);shape.Clip=clip;}}}}
 public void SetRotation(ElementEdit e){foreach(var shape in Shapes)if(shape.Element==e.Index){shape.Rotation=e.Rotation;shape.Pivot=ElementTransform.Center(e);}}
 public void Dispose(){foreach(var item in Shapes)item.Dispose();Shapes.Clear();}
}
public static class VectorArt {
 public static string Svg(LabelSettings s){using(var scene=Build(s))return SceneOutput.Svg(scene,new RectangleF(0,0,(float)s.Width,(float)s.Height));}
 public static void Pdf(string path,LabelSettings s){SceneOutput.Pdf(path,OutputPlan.Create(s));}
 public static FontFamily Family(string name){try{return new FontFamily(string.IsNullOrWhiteSpace(name)?"Arial":name);}catch{return new FontFamily("Arial");}}
 public static FontStyle Style(FontFamily family,bool bold){var desired=bold?FontStyle.Bold:FontStyle.Regular;if(family.IsStyleAvailable(desired))return desired;foreach(var fallback in new[]{FontStyle.Regular,FontStyle.Bold,FontStyle.Italic,FontStyle.Bold|FontStyle.Italic})if(family.IsStyleAvailable(fallback))return fallback;return FontStyle.Regular;}
 static RectangleF Rect(double x,double y,double w,double h){return new RectangleF((float)x,(float)y,(float)w,(float)h);}
 static void Text(VectorScene scene,string text,string family,double size,bool bold,bool center,RectangleF bounds,bool nowrap,int element=-1){if(string.IsNullOrEmpty(text))return;var path=new GraphicsPath();try{using(var ff=Family(family))using(var fmt=new StringFormat(StringFormat.GenericTypographic)){fmt.Alignment=center?StringAlignment.Center:StringAlignment.Near;fmt.Trimming=StringTrimming.None;if(nowrap)fmt.FormatFlags|=StringFormatFlags.NoWrap;path.AddString(text,ff,(int)Style(ff,bold),(float)(size*25.4/72),bounds,fmt);}scene.Shapes.Add(new ArtShape{Path=path,Clip=bounds,Element=element});}catch{path.Dispose();throw;}}
 public static VectorScene Build(LabelSettings s){WorkContext.Check();if(s.Variables.Count>0){var record=BatchData.Record(s,new string[0],new List<ColumnBinding>(),-1,0,1,DateTime.Today);if(record.Error!=null)throw new InvalidDataException(record.Error);s=record.Label;}Engine.Validate(s);var scene=new VectorScene{Width=s.Width,Height=s.Height};try{
  for(int i=0;i<s.Texts.Count;i++){WorkContext.Check();var t=s.Texts[i];Text(scene,t.Text,t.FontName,t.Size,t.Bold,t.Center,Rect(t.X,t.Y,t.Width,t.Height),false,i);}
  if(!s.HideBarcode){double k=s.Dpi/25.4;int m=Engine.Module(s),total=Engine.Modules(s),quiet=Engine.Quiet(s.Kind);string bits=Engine.CodeBits(s),value=Engine.Caption(s);
  int x=(int)Math.Round(s.BarX*k)+(int)Math.Round((s.BarWidth*k-total*m)/2),y=(int)Math.Round(s.BarY*k),h=(int)Math.Round(s.BarHeight*k),bearer=s.Kind==14?5*m:0;
  var bars=new GraphicsPath();scene.Shapes.Add(new ArtShape{Path=bars,Clip=Rect(0,0,s.Width,s.Height),Bars=true});
  if(bearer>0){bars.AddRectangle(Rect(x/k,y/k,total*m/k,bearer/k));bars.AddRectangle(Rect(x/k,(y+bearer+h)/k,total*m/k,bearer/k));y+=bearer;}
  int guard=s.Digits?Math.Min(5*m,(int)(s.DigitSize*s.Dpi/72*.45)):0;
  for(int i=0;i<bits.Length;i++)if(bits[i]=='1'){bool retail=s.Kind==13||s.Kind==8||s.Kind==12;bool special=retail&&(i<3||i>=bits.Length-3||(i>=(s.Kind==8?31:45)&&i<(s.Kind==8?36:50))||(s.Kind==12&&(i<10||i>=85)));bars.AddRectangle(Rect((x+(quiet+i)*m)/k,y/k,m/k,(h+(special?guard:0))/k));}
  y+=bearer;double captionY=(y+h)/k,captionH=s.DigitSize*25.4/72*1.5;
  Action<string,int,int> digits=delegate(string text,int xx,int width){Text(scene,text,"Arial",s.DigitSize,false,true,Rect(xx/k,captionY,width/k,captionH),true);};
  if(s.Digits){if(s.Kind==13){digits(value.Substring(0,1),x,10*m);digits(value.Substring(1,6),x+14*m,42*m);digits(value.Substring(7,6),x+61*m,42*m);}else if(s.Kind==8){digits(value.Substring(0,4),x+10*m,28*m);digits(value.Substring(4,4),x+43*m,28*m);}else if(s.Kind==12){digits(value.Substring(0,1),x,8*m);digits(value.Substring(1,5),x+19*m,35*m);digits(value.Substring(6,5),x+59*m,35*m);digits(value.Substring(11,1),x+105*m,8*m);}else digits(value,x,total*m);}
  }for(int i=0;i<s.Symbols.Count;i++){var symbol=s.Symbols[i];if(symbol.Image!=null||symbol.Matrix!=null){Assets.Add(scene,symbol,-3-i,s.Dpi);continue;}if(symbol.Code!=null){using(var source=Build(symbol.Code.Settings()))using(var matrix=new Matrix((float)(symbol.Width/symbol.Code.Width),0,0,(float)(symbol.Height/Engine.BarcodeHeight(symbol.Code.Settings())),(float)(symbol.X-symbol.Code.SourceX*symbol.Width/symbol.Code.Width),(float)(symbol.Y-symbol.Code.SourceY*symbol.Height/Engine.BarcodeHeight(symbol.Code.Settings())))){foreach(var shape in source.Shapes){var copy=(GraphicsPath)shape.Path.Clone();copy.Transform(matrix);var corners=new[]{new PointF(shape.Clip.Left,shape.Clip.Top),new PointF(shape.Clip.Right,shape.Clip.Bottom)};matrix.TransformPoints(corners);scene.Shapes.Add(new ArtShape{Path=copy,Bars=shape.Bars,Element=-3-i,Clip=shape.Bars?Rect(0,0,s.Width,s.Height):RectangleF.FromLTRB(corners[0].X,corners[0].Y,corners[1].X,corners[1].Y)});}}continue;}var path=DepositArt.Create();var bounds=path.GetBounds();using(var matrix=new Matrix((float)(symbol.Width/bounds.Width),0,0,(float)(symbol.Height/bounds.Height),(float)symbol.X,(float)symbol.Y))path.Transform(matrix);scene.Shapes.Add(new ArtShape{Path=path,Clip=Rect(symbol.X,symbol.Y,symbol.Width,symbol.Height),Element=-3-i});}
  foreach(var shape in scene.Shapes){var e=ElementTransform.Get(s,shape.Element);shape.Rotation=e.Rotation;shape.Pivot=ElementTransform.Center(e);if(shape.Bars)shape.Clip=ElementTransform.LocalBounds(e);}
  var order=new Dictionary<ArtShape,int>();for(int i=0;i<scene.Shapes.Count;i++)order[scene.Shapes[i]]=i;scene.Shapes.Sort((a,b)=>{int layer=Elements.Layer(s,a.Element).CompareTo(Elements.Layer(s,b.Element));return layer!=0?layer:order[a].CompareTo(order[b]);});return scene;
 }catch{scene.Dispose();throw;}}
 public static Bitmap Raster(LabelSettings s,double dpi,bool mono){Engine.Validate(s);double pixels=s.Width*s.Height*dpi*dpi/(25.4*25.4);if(pixels>40000000)dpi=Math.Sqrt(40000000*25.4*25.4/(s.Width*s.Height));int w=Math.Max(1,(int)Math.Round(s.Width*dpi/25.4)),h=Math.Max(1,(int)Math.Round(s.Height*dpi/25.4));var bitmap=new Bitmap(w,h,PixelFormat.Format24bppRgb);bitmap.SetResolution((float)dpi,(float)dpi);try{using(var g=Graphics.FromImage(bitmap))using(var scene=Build(s)){g.Clear(Color.White);scene.Draw(g,new RectangleF(0,0,(float)(s.Width*dpi/25.4),(float)(s.Height*dpi/25.4)),mono);}return bitmap;}catch{bitmap.Dispose();throw;}}
 static string F(double v){return v.ToString("0.#####",CultureInfo.InvariantCulture);}
 public static string PathData(GraphicsPath path,bool svg){var b=new StringBuilder();var pts=path.PathPoints;var types=path.PathTypes;for(int i=0;i<pts.Length;i++){int type=types[i]&7;if(type==0)b.Append(svg?"M":"").Append(F(pts[i].X)).Append(' ').Append(F(pts[i].Y)).Append(svg?" ":" m\n");else if(type==1)b.Append(svg?"L":"").Append(F(pts[i].X)).Append(' ').Append(F(pts[i].Y)).Append(svg?" ":" l\n");else if(type==3&&i+2<pts.Length){b.Append(svg?"C":"");for(int j=0;j<3;j++)b.Append(F(pts[i+j].X)).Append(' ').Append(F(pts[i+j].Y)).Append(' ');b.Append(svg?"":"c\n");i+=2;}if((types[i]&128)!=0)b.Append(svg?"Z ":"h\n");}return b.ToString();}
}
}
